// ===================== CONFIG =====================
const CONFIG = {
  TAMANHO_LOTE: 10,         // quantos ContactIds por consulta na API /Contacts
  MAX_PAGINAS_HTTP: 500      // mesmo valor de maxPages do node "Buscar Interações Ploomes (18 meses)"
};
// ==================================================

// Junta todas as páginas retornadas pela paginação do node HTTP
const contactIds = new Set();
let totalInteracoes = 0;
let semContactId = 0;

items.forEach(item => {
  const j = item.json || {};
  const pag = j.pagination;
  const paginas = pag && Array.isArray(pag.allParsedBodies) ? pag.allParsedBodies : [j.parsedBody];

  if (pag && (pag.truncated || pag.pageCount >= CONFIG.MAX_PAGINAS_HTTP)) {
    console.warn('ATENÇÃO: paginação de InteractionRecords pode estar incompleta (pageCount=' + pag.pageCount + ', truncated=' + !!pag.truncated + '). Aumente maxPages.');
  }

  paginas.forEach(pb => {
    const registros = pb && Array.isArray(pb.value) ? pb.value : (Array.isArray(pb) ? pb : []);
    registros.forEach(r => {
      totalInteracoes++;
      const id = r && r.ContactId != null ? String(r.ContactId).trim() : '';
      if (/^\d+$/.test(id) && id !== '0') contactIds.add(id);
      else semContactId++;
    });
  });
});

// Deduplicação: várias interações do mesmo ContactId viram um único ContactId
const ids = Array.from(contactIds);
console.log('Interações lidas: ' + totalInteracoes + ' | sem ContactId: ' + semContactId + ' | ContactIds únicos: ' + ids.length);

// Lotes de ContactIds para consultar a API /Contacts com $filter=Id eq X or Id eq Y ...
const lotes = [];
for (let i = 0; i < ids.length; i += CONFIG.TAMANHO_LOTE) {
  const lote = ids.slice(i, i + CONFIG.TAMANHO_LOTE);
  lotes.push({
    json: {
      lote: lotes.length + 1,
      quantidade: lote.length,
      ids: lote,
      filtro: lote.map(id => 'Id eq ' + id).join(' or '),
      total_interacoes: totalInteracoes,
      total_contatos_unicos: ids.length
    }
  });
}

// Sem interações: consulta neutra (Id eq 0 não retorna nada) só para manter o ramo vivo até a comparação
if (lotes.length === 0) {
  lotes.push({ json: { lote: 1, quantidade: 0, ids: [], filtro: 'Id eq 0', total_interacoes: totalInteracoes, total_contatos_unicos: 0 } });
}

return lotes;

// ===================== CONFIG =====================
// Ajuste aqui os nomes de campo caso o relatório do Datalab ou a API do Ploomes usem outros.
const CONFIG = {
  FUSO_HORAS: -3,               // America/Sao_Paulo (sem horário de verão)
  INCLUIR_SO_PLOOMES: false,    // true = também lista contatos do Ploomes sem cadastro no Gestor
  NODE_INTERACOES: 'Buscar Interações Ploomes (18 meses)',
  SO_DOCUMENTO: true,           // true = cliente do Gestor COM CPF/CNPJ só vincula ao Ploomes por documento (sem e-mail/telefone)
  MAX_POR_CHAVE: 2,             // e-mail/telefone compartilhado por mais contatos (Ploomes) ou clientes (Gestor) que isso é genérico e não vincula
  // Campos do relatório do Datalab
  DL_CODIGO: ['codigo', 'codigo_cliente', 'cod_cliente'],
  DL_NOME: ['nome_razao_social', 'nome_razao', 'nome/razao', 'razao_social', 'nome'],
  DL_DOC: ['cnpj_cpf', 'documento', 'cpf_cnpj', 'cpf', 'cnpj'],
  DL_EMAIL: ['email', 'e_mail'],
  DL_FONE: ['telefone', 'fone', 'celular'],
  DL_TIPO: ['tipo_pessoa'],
  DL_VENDEDOR: ['vendedor', 'nome_vendedor', 'vendedor_nome', 'representante'],
  DL_EMPRESA: ['_razaoOrigem', 'empresa', 'nome_empresa', 'empresa_nome', 'razao_empresa', 'filial', 'cod_empresa', 'id_empresa'],
  DL_DATA_VENDA: ['data_ultima_venda', 'ultima_venda', 'dt_ultima_venda', 'data_ultima_compra', 'ultima_compra', 'data_venda', 'dt_venda'],
  // Campos da API /Contacts do Ploomes
  PL_NOME: ['Name', 'LegalName'],
  PL_DOC: ['CPF', 'CNPJ', 'Register'],
  PL_FONE: ['PhoneNumber', 'SearchPhoneNumber'],
  STATUS: { vermelho: '🔴 Vermelho', laranja: '🟠 Laranja', amarelo: '🟡 Amarelo', azul: '🔵 Azul', verde: '🟢 Verde' }
};
// ==================================================

const DIA = 86400000;
const OFF = CONFIG.FUSO_HORAS * 3600000;
const HOJE = Math.floor((Date.now() + OFF) / DIA); // dia de hoje no fuso local (dias desde 1970)

const soDig = v => String(v ?? '').replace(/\D/g, '');
const iguais = d => /^(\d)\1*$/.test(d);
const add = (l, v) => { if (v && !l.includes(v)) l.push(v); };
function primeiro(o, campos) {
  for (const c of campos) { const v = o[c]; if (v != null && String(v).trim() !== '') return v; }
  return null;
}

// CPF = 11 dígitos | CNPJ = 14 dígitos (recupera zeros à esquerda)
function doc(v) {
  const d = soDig(v);
  if (!d || iguais(d)) return null;
  if (d.length >= 9 && d.length <= 11) return d.padStart(11, '0');
  if (d.length >= 12 && d.length <= 14) return d.padStart(14, '0');
  return null;
}
function mascara(d) {
  return d.length === 11
    ? d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4')
    : d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');
}
function emails(v) {
  return String(v ?? '').toLowerCase().split(/[;,\s]+/).filter(e => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e));
}
// Chave de telefone = DDD + 8 últimos dígitos
function fone(v) {
  let d = soDig(v).replace(/^0+/, '');
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  if (d.length !== 10 && d.length !== 11) return null;
  const n = d.slice(-8);
  return iguais(n) ? null : d.slice(0, 2) + n;
}

// Converte data (ISO, ISO com fuso, DD/MM/AAAA, epoch ms, serial do Excel) em "dia" local
function dia(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'number') {
    if (v > 1e11) return Math.floor((v + OFF) / DIA);
    if (v > 20000 && v < 80000) return Math.floor(v) - 25569;
    return null;
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (m) return Date.UTC(+m[3], +m[2] - 1, +m[1]) / DIA;
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})(.*)$/);
  if (!m || +m[1] < 1900) return null;
  if (/(Z|[+-]\d{2}:?\d{2})$/.test(m[4])) {
    const t = Date.parse(s);
    return isNaN(t) ? null : Math.floor((t + OFF) / DIA);
  }
  return Date.UTC(+m[1], +m[2] - 1, +m[3]) / DIA;
}
function fmt(d) {
  if (d == null) return '';
  const x = new Date(d * DIA);
  return String(x.getUTCDate()).padStart(2, '0') + '/' + String(x.getUTCMonth() + 1).padStart(2, '0') + '/' + x.getUTCFullYear();
}
const maior = (a, b) => a == null ? b : b == null ? a : Math.max(a, b);

// Status pela data da ÚLTIMA COMPRA NO GESTOR (o contato do Ploomes é só informativo)
// Faixas exclusivas: verde <=15 | azul 16-30 | amarelo 31-60 | laranja 61-90 | vermelho >90 ou sem registro
function statusDe(ref) {
  if (ref == null) return 'vermelho';
  const dias = HOJE - ref;
  if (dias <= 15) return 'verde';
  if (dias <= 30) return 'azul';
  if (dias <= 60) return 'amarelo';
  if (dias <= 90) return 'laranja';
  return 'vermelho';
}

// ---------- 1) Interação mais recente por ContactId (18 meses) ----------
const inter = $node[CONFIG.NODE_INTERACOES].json || {};
const paginas = inter.pagination && Array.isArray(inter.pagination.allParsedBodies) ? inter.pagination.allParsedBodies : [inter.parsedBody];
const ultimaInteracao = new Map();
paginas.forEach(pb => (pb && Array.isArray(pb.value) ? pb.value : []).forEach(r => {
  const id = r && r.ContactId != null ? String(r.ContactId) : '';
  const d = dia(r && r.Date);
  if (id && d != null && d <= HOJE) ultimaInteracao.set(id, maior(ultimaInteracao.get(id), d)); // ignora interações futuras (agendadas)
}));

// ---------- 2) Separar entradas: contatos Ploomes (HTTP) x linhas do Datalab ----------
const plMap = new Map();
const plVistos = new Set();
const dlRows = [];
function expandir(o) {
  if (!o || typeof o !== 'object') return;
  if (Array.isArray(o.dados)) { o.dados.forEach(expandir); return; }
  if (primeiro(o, CONFIG.DL_CODIGO) != null || primeiro(o, CONFIG.DL_DOC) != null || primeiro(o, CONFIG.DL_NOME) != null) dlRows.push(o);
}

items.forEach(it => {
  const j = it.json || {};
  if (j.parsedBody === undefined || j.status === undefined) { expandir(j); return; }
  const lista = j.parsedBody && Array.isArray(j.parsedBody.value) ? j.parsedBody.value : [];
  lista.forEach(c => {
    if (!c || c.Id == null || plVistos.has(String(c.Id))) return;
    const id = String(c.Id);
    plVistos.add(id);
    const docs = [], ems = [], fones = [], tels = [];
    CONFIG.PL_DOC.forEach(f => add(docs, doc(c[f])));
    // Pessoa sem documento próprio herda o CNPJ/CPF da empresa vinculada no Ploomes
    if (!docs.length && c.Company && typeof c.Company === 'object') CONFIG.PL_DOC.forEach(f => add(docs, doc(c.Company[f])));
    emails(c.Email).forEach(e => add(ems, e));
    (Array.isArray(c.Phones) ? c.Phones : []).forEach(p => CONFIG.PL_FONE.forEach(f => {
      const n = fone(p && p[f]);
      if (n) { add(fones, n); add(tels, String(p[f]).trim()); }
    }));
    // Cada contato do Ploomes fica separado; o vínculo junta os contatos depois (por documento, e-mail ou telefone)
    const chave = 'id:' + id;
    let p = plMap.get(chave);
    if (!p) { p = { ids: [], nome: '', docs: [], emails: [], fones: [], tel: '', email: '', uc: null, usado: false }; plMap.set(chave, p); }
    add(p.ids, id);
    if (!p.nome) p.nome = String(primeiro(c, CONFIG.PL_NOME) || '').trim();
    docs.forEach(v => add(p.docs, v));
    ems.forEach(v => add(p.emails, v));
    fones.forEach(v => add(p.fones, v));
    if (!p.tel && tels[0]) p.tel = tels[0];
    if (!p.email && ems[0]) p.email = ems[0];
    p.uc = maior(p.uc, ultimaInteracao.get(id));
  });
});

const idxDoc = new Map(), idxEmail = new Map(), idxFone = new Map();
const indexar = (m, k, p) => { if (!m.has(k)) m.set(k, []); m.get(k).push(p); };
plMap.forEach(p => {
  p.docs.forEach(k => indexar(idxDoc, k, p));
  p.emails.forEach(k => indexar(idxEmail, k, p));
  p.fones.forEach(k => indexar(idxFone, k, p));
});

// ---------- 3) Clientes do Gestor: 1 cliente = 1 grupo (várias vendas/empresas fundidas) ----------
const grupos = [];
const porChave = new Map();
let fundidos = 0;
dlRows.forEach((r, i) => {
  const docs = [];
  CONFIG.DL_DOC.forEach(f => add(docs, doc(r[f])));
  const cod = primeiro(r, CONFIG.DL_CODIGO);
  const codS = cod == null ? '' : String(cod).trim();
  const ems = emails(primeiro(r, CONFIG.DL_EMAIL));
  const fs = [];
  CONFIG.DL_FONE.forEach(f => add(fs, fone(r[f])));
  const nome = String(primeiro(r, CONFIG.DL_NOME) ?? '').trim();

  // Chave do cliente = código do Gestor (é o mesmo nas 4 empresas). Sem código, usa o CPF/CNPJ.
  // Não agrupa por documento quando há código: um mesmo CNPJ pode ter vários cadastros (ex.: unidades de uma mesma rede).
  const chaves = codS ? ['cod:' + codS] : docs.map(d => 'doc:' + d);
  if (!chaves.length) chaves.push(ems[0] ? 'email:' + ems[0] : fs[0] ? 'fone:' + fs[0] : nome ? 'nome:' + nome.toUpperCase() : 'linha:' + i);

  let g = null;
  for (const k of chaves) if (porChave.has(k)) { g = porChave.get(k); break; }
  if (g) fundidos++;
  else { g = { cods: [], nome: '', docs: [], emails: [], fones: [], tel: '', email: '', vend: [], tipo: [], uv: null, empUv: [] }; grupos.push(g); }
  chaves.forEach(k => porChave.set(k, g));

  add(g.cods, codS);
  docs.forEach(v => add(g.docs, v));
  ems.forEach(v => add(g.emails, v));
  fs.forEach(v => add(g.fones, v));
  if (!g.nome) g.nome = nome;
  const vd = primeiro(r, CONFIG.DL_VENDEDOR);
  if (vd != null) add(g.vend, String(vd).trim());
  const tp = primeiro(r, CONFIG.DL_TIPO);
  if (tp != null) add(g.tipo, String(tp).trim());
  if (!g.tel) { const t = primeiro(r, CONFIG.DL_FONE); if (t != null) g.tel = String(t).trim(); }
  if (!g.email) g.email = String(primeiro(r, CONFIG.DL_EMAIL) ?? '').trim();
  // Última venda: guarda a(s) empresa(s) da linha com a data mais recente (empate = todas)
  let dv = null;
  CONFIG.DL_DATA_VENDA.forEach(f => { dv = maior(dv, dia(r[f])); });
  if (dv != null) {
    const emp = primeiro(r, CONFIG.DL_EMPRESA);
    const empS = emp == null ? '' : String(emp).replace(/\s+/g, ' ').trim();
    if (g.uv == null || dv > g.uv) { g.uv = dv; g.empUv = empS ? [empS] : []; }
    else if (dv === g.uv) add(g.empUv, empS);
  }
});

// ---------- 4) Vincular Gestor x Ploomes (CPF/CNPJ primeiro; e-mail/telefone só sem conflito de documento) ----------
// E-mail/telefone "genérico": compartilhado por mais de MAX_POR_CHAVE contatos do Ploomes
// ou por mais de MAX_POR_CHAVE clientes do Gestor (ex.: lojasproprias@...). Esses não vinculam.
const usoGestor = new Map();
grupos.forEach(g => g.emails.map(e => 'e:' + e).concat(g.fones.map(f => 'f:' + f))
  .forEach(k => usoGestor.set(k, (usoGestor.get(k) || 0) + 1)));
const genericoGestor = k => (usoGestor.get(k) || 0) > CONFIG.MAX_POR_CHAVE;
// CPF/CNPJ "compartilhado": o mesmo documento em mais de um cliente do Gestor (ex.: várias unidades com o mesmo CNPJ).
// Nesse caso o documento sozinho não diz qual cliente o contato atende: exige também e-mail ou telefone em comum.
const usoDoc = new Map();
grupos.forEach(g => g.docs.forEach(d => usoDoc.set(d, (usoDoc.get(d) || 0) + 1)));
const unicos = l => (l && l.reduce((n, p) => n + p.ids.length, 0) <= CONFIG.MAX_POR_CHAVE ? l : []);

function vincular(g) {
  const achados = new Set();
  const temContatoComum = p => p.emails.some(e => g.emails.includes(e) && !genericoGestor('e:' + e)) ||
    p.fones.some(f => g.fones.includes(f) && !genericoGestor('f:' + f));
  g.docs.forEach(d => {
    let lista = idxDoc.get(d) || [];
    if ((usoDoc.get(d) || 0) > 1) lista = lista.filter(temContatoComum);
    lista.forEach(p => achados.add(p));
  });
  if (!achados.size && !(CONFIG.SO_DOCUMENTO && g.docs.length)) {
    const semConflito = p => !g.docs.length || !p.docs.length;
    g.emails.filter(e => !genericoGestor('e:' + e)).forEach(e => unicos(idxEmail.get(e)).filter(semConflito).forEach(p => achados.add(p)));
    if (!achados.size) g.fones.filter(f => !genericoGestor('f:' + f)).forEach(f => unicos(idxFone.get(f)).filter(semConflito).forEach(p => achados.add(p)));
  }
  return Array.from(achados);
}

const cont = { vermelho: 0, laranja: 0, amarelo: 0, azul: 0, verde: 0 };
const linhas = [];
let vinculados = 0, semContato = 0, semVenda = 0;

function linha(cg, cp, docs, nome, tel, email, vend, uc, uv, emp, tipo) {
  const ref = uv;                       // só a última compra no Gestor define o status
  const s = statusDe(ref);
  cont[s]++;
  if (uc == null) semContato++;
  if (uv == null) semVenda++;
  linhas.push({
    cg, cp, doc: docs.map(mascara).join(' / '), tp: tipo || '', nome, tel, email,
    uc: fmt(uc), uv: fmt(uv), emp, vend, st: CONFIG.STATUS[s], _r: ref == null ? -1 : ref
  });
}

grupos.forEach(g => {
  const pls = vincular(g);
  let uc = null;
  const ids = [];
  pls.forEach(p => { p.usado = true; uc = maior(uc, p.uc); p.ids.forEach(id => add(ids, id)); });
  if (pls.length) vinculados++;
  const p0 = pls[0] || {};
  linha(g.cods.join(' / '), ids.join(' / '), g.docs, g.nome || p0.nome || '',
    g.tel || p0.tel || '', g.email || p0.email || '', g.vend.join(' / '), uc, g.uv, g.empUv.join(' / '), g.tipo.join(' / '));
});

if (CONFIG.INCLUIR_SO_PLOOMES) {
  plMap.forEach(p => { if (!p.usado) linha('', p.ids.join(' / '), p.docs, p.nome, p.tel, p.email, '', p.uc, null, '', ''); });
}

// Ordem: data da última compra no Gestor, da mais recente para a mais antiga (sem compra ao final); empate por nome
linhas.sort((a, b) => b._r - a._r || String(a.nome).localeCompare(String(b.nome), 'pt-BR', { sensitivity: 'base' }));
linhas.forEach(l => { delete l._r; });

// ---------- 5) Resumo para o e-mail ----------
const ref = { hoje: fmt(HOJE), d15: fmt(HOJE - 15), d30: fmt(HOJE - 30), d60: fmt(HOJE - 60), d90: fmt(HOJE - 90) };
const faixas = [
  ['verde', 'Última compra de ' + ref.d15 + ' até hoje'],
  ['azul', 'Última compra de ' + ref.d30 + ' a ' + fmt(HOJE - 16)],
  ['amarelo', 'Última compra de ' + ref.d60 + ' a ' + fmt(HOJE - 31)],
  ['laranja', 'Última compra de ' + ref.d90 + ' a ' + fmt(HOJE - 61)],
  ['vermelho', 'Sem compra há mais de 90 dias (antes de ' + ref.d90 + ') ou sem registro']
];
// Distribuição por status para o e-mail (o HTML é montado em "Montar E-mail do Relatório")
const faixasStatus = faixas.map(([k, txt]) => ({ chave: k, status: CONFIG.STATUS[k], texto: txt, qtd: cont[k] }));

if (dlRows.length && grupos.every(g => !g.docs.length)) {
  console.warn('Nenhum CPF/CNPJ encontrado no Datalab. Campos recebidos: ' + Object.keys(dlRows[0]).join(', ') + ' -> ajuste CONFIG.DL_DOC.');
}
if (dlRows.length && grupos.every(g => !g.tipo.length)) {
  console.warn('Campo tipo_pessoa não encontrado no Datalab. Campos recebidos: ' + Object.keys(dlRows[0]).join(', ') + ' -> ajuste CONFIG.DL_TIPO.');
}
if (dlRows.length && grupos.every(g => g.uv == null)) {
  console.warn('Nenhuma data de venda encontrada no Datalab. Campos recebidos: ' + Object.keys(dlRows[0]).join(', ') + '. Confira se o relatório traz a data da última venda e ajuste CONFIG.DL_DATA_VENDA.');
}
if (grupos.some(g => g.uv != null) && grupos.every(g => !g.empUv.length)) {
  console.warn('Nenhuma empresa encontrada nas linhas de venda do Datalab. Campos recebidos: ' + Object.keys(dlRows[0]).join(', ') + ' -> ajuste CONFIG.DL_EMPRESA.');
}
const tamanho = JSON.stringify(linhas).length;
if (tamanho > 900000) console.warn('Saída com ' + tamanho + ' bytes: perto do teto de 1 MiB do node Código (CODE_NODE_MAX_OUTPUT_BYTES).');
console.log('Linhas Datalab: ' + dlRows.length + ' | clientes Gestor: ' + grupos.length + ' | contatos Ploomes: ' + plVistos.size +
  ' | vinculados: ' + vinculados + ' | linhas: ' + linhas.length + ' | status: ' + JSON.stringify(cont));

return [{ json: {
  data_execucao: ref.hoje,
  referencias: ref,
  total_clientes: linhas.length,
  total_registros_gestor: dlRows.length,
  registros_gestor_fundidos: fundidos,
  total_contatos_ploomes: plVistos.size,
  clientes_vinculados_ploomes: vinculados,
  sem_contato_registrado: semContato,
  sem_venda_registrada: semVenda,
  qtd_vermelho: cont.vermelho, qtd_laranja: cont.laranja, qtd_amarelo: cont.amarelo, qtd_azul: cont.azul, qtd_verde: cont.verde,
  faixas: faixasStatus,
  linhas
} }];

// Recupera as linhas (1 por cliente) que o nó "Criar Planilha" não repassa.
// CONFIG: datas gravadas como AAAA-MM-DD; com valueInputOption USER_ENTERED o Google Sheets reconhece como DATA
// (independe do idioma da planilha) e o filtro por data funciona. DD/MM/AAAA como texto não vira data.
const CONFIG = { CAMPOS_DATA: ['uc', 'uv'] };
const iso = v => { const m = String(v || '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/); return m ? m[3] + '-' + m[2] + '-' + m[1] : ''; };
const origem = $node["Consolidar Clientes e Calcular Status"].json;
const linhas = Array.isArray(origem.linhas) ? origem.linhas : [];
console.log('Linhas a gravar: ' + linhas.length);
return linhas.map(l => {
  const o = Object.assign({}, l);
  CONFIG.CAMPOS_DATA.forEach(c => { o[c] = iso(o[c]); });
  return { json: o };
});

// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  nomeEmpresa: "NOME DA EMPRESA",
  titulo: "Monitoramento comercial da carteira",
  assunto: "Monitoramento comercial da carteira - {data}",
  rodape: "Mensagem automática do sistema comercial NOME DA EMPRESA."
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + wpEsc(o.preheader || "") + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='wp-bg' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wp-wrap' style='width:600px;max-width:600px;'>";
  // Marca
  h += "<tr><td class='wp-pad' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='wp-t' style='" + WP_F + "font-size:22px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "<td align='right' class='wp-m' style='" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(o.empresa || "") + (o.rotuloDireita ? "<br>" + o.rotuloDireita : "") + "</td>";
  h += "</tr></table></td></tr>";
  // Cartão
  h += "<tr><td bgcolor='#FEFEFE' class='wp-card' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:12px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:12px 12px 0 0;'>&nbsp;</td></tr>";
  if (eyebrow || o.titulo || o.saudacao) {
    h += "<tr><td class='wp-pad' style='padding:32px 32px 8px 32px;'>";
    if (eyebrow) h += "<p class='wp-eb' style='margin:0 0 8px 0;" + WP_F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(eyebrow) + "</p>";
    if (o.titulo) h += "<h1 class='wp-h1 wp-t' style='margin:0 0 12px 0;" + WP_F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + wpEsc(o.titulo) + "</h1>";
    if (o.saudacao) h += "<p class='wp-t' style='margin:0;" + WP_F + "font-size:15px;color:#303030;mso-line-height-rule:exactly;line-height:23px;'>" + o.saudacao + "</p>";
    if (o.subSaudacao) h += "<p class='wp-m' style='margin:6px 0 0 0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + o.subSaudacao + "</p>";
    h += "</td></tr>";
  }
  if (o.heroValor !== undefined && o.heroValor !== null) {
    const tam = Math.min(o.heroTam || 44, 48);
    h += "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F1F2EC' style='background:#F1F2EC;border-radius:8px;padding:20px;'>";
    if (o.heroEyebrow && o.eyebrow && o.eyebrow !== o.heroEyebrow) h += "<p class='wp-c-medio' style='margin:0 0 6px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#5A6344;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(o.heroEyebrow) + "</p>";
    h += "<p class='wp-hero wp-c-medio' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:#5A6344;letter-spacing:-1px;mso-line-height-rule:exactly;line-height:" + (tam + 4) + "px;'>" + wpEsc(o.heroValor) + "</p>";
    if (o.heroSub) h += "<p class='wp-c-medio' style='margin:6px 0 0 0;" + WP_F + "font-size:14px;color:#5A6344;mso-line-height-rule:exactly;line-height:20px;'>" + o.heroSub + "</p>";
    if (o.heroBarra !== undefined && o.heroBarra !== null) {
      const w = Math.max(0, Math.min(100, Math.round(o.heroBarra)));
      h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:14px;'><tr><td bgcolor='#E3E6D8' style='background:#E3E6D8;border-radius:5px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" +
        "<td width='" + w + "%' height='10' bgcolor='#5A6344' style='height:10px;background:#5A6344;border-radius:5px;font-size:0;line-height:0;'>&nbsp;</td>" +
        (w < 100 ? "<td height='10' style='height:10px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table></td></tr></table>";
    }
    if (o.heroNota) h += "<p class='wp-c-medio' style='margin:10px 0 0 0;" + WP_F + "font-size:12px;color:#5A6344;mso-line-height-rule:exactly;line-height:18px;'>" + o.heroNota + "</p>";
    h += "</td></tr></table></td></tr>";
  }
  h += o.miolo || "";
  h += "<tr><td style='height:24px;font-size:0;line-height:0;'>&nbsp;</td></tr>";
  h += "</table></td></tr>";
  // Rodapé
  const linhasRodape = o.rodape || [];
  h += "<tr><td class='wp-pad' align='center' style='padding:24px 24px 0 24px;'>";
  for (let i = 0; i < linhasRodape.length; i++) {
    h += "<p class='wp-m' style='margin:" + (i > 0 ? "6px" : "0") + " 0 0 0;" + WP_F + "font-size:12px;color:" + (i === linhasRodape.length - 1 ? "#8A90A0" : "#6B7280") + ";mso-line-height-rule:exactly;line-height:18px;'>" + linhasRodape[i] + "</p>";
  }
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

// Parágrafo livre (HTML já escapado pelo chamador)
function wpTexto(html) {
  return "<tr><td class='wp-pad' style='padding:8px 32px;'><p class='wp-m' style='margin:0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + html + "</p></td></tr>";
}

// Título de seção com subtítulo
function wpSecao(titulo, sub) {
  return "<tr><td class='wp-pad' style='padding:24px 32px 12px 32px;'>" +
    "<p class='wp-t' style='margin:0;" + WP_F + "font-size:16px;font-weight:bold;color:#303030;mso-line-height-rule:exactly;line-height:22px;'>" + wpEsc(titulo) + "</p>" +
    (sub ? "<p class='wp-m' style='margin:4px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:18px;'>" + sub + "</p>" : "") + "</td></tr>";
}

// Cartões de indicador lado a lado. lista: [{rotulo, valor, estilo, sub}], titulo (opcional) vira um rótulo pequeno acima.
// Sem estilo, o primeiro é "medio" (verde-oliva) e os outros "neutro", como no Guardião.
function wpKpis(lista, titulo) {
  const n = lista.length;
  const larg = (100 / n).toFixed(2);
  let h = "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'>";
  if (titulo) h += "<p class='wp-m' style='margin:0 0 8px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(titulo) + "</p>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  // Valor longo (ex.: R$ 99.716,16) com 3 ou mais cartões lado a lado: fonte menor para caber numa linha.
  const maiorValor = lista.reduce(function (m, k) { return Math.max(m, String(k.valor === undefined ? "" : k.valor).length); }, 0);
  const tam = n >= 3 && maiorValor > 9 ? 20 : n >= 2 && maiorValor > 14 ? 20 : 26;
  for (let i = 0; i < n; i++) {
    const k = lista[i];
    const nome = WP_ESTILOS[k.estilo] ? k.estilo : (i === 0 ? "medio" : "neutro");
    const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
    const cls = nome === "forte" ? "medio" : nome;
    const pad = n === 1 ? "" : (i === 0 ? "padding-right:6px;" : (i === n - 1 ? "padding-left:6px;" : "padding:0 3px;"));
    h += "<td class='wp-kpi' width='" + larg + "%' valign='top' style='width:" + larg + "%;" + pad + "'>" +
      "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:8px;padding:16px;'>" +
      "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:" + (tam + 6) + "px;white-space:nowrap;'>" + wpEsc(k.valor) + "</p>" +
      "<p class='wp-c-" + cls + "' style='margin:4px 0 0 0;" + WP_F + "font-size:13px;color:" + (nome === "neutro" ? "#5B6170" : e.cor) + ";mso-line-height-rule:exactly;line-height:18px;'>" + wpEsc(k.rotulo) + "</p>" +
      (k.sub ? "<p class='wp-m' style='margin:2px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(k.sub) + "</p>" : "") +
      "</td></tr></table></td>";
  }
  return h + "</tr></table></td></tr>";
}

// Tabela. colunas: [{t, a: "left"|"right"|"center", w, oculta}], linhas: [[html da célula, ...], ...]
// oculta = some em tela pequena. nota (opcional): texto abaixo da tabela.
function wpTabela(colunas, linhas, nota) {
  let h = "<tr><td class='wp-pad' style='padding:4px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='wp-bd' style='border:1px solid #E5E7EB;border-radius:8px;border-collapse:separate;'><tr>";
  for (let c = 0; c < colunas.length; c++) {
    const col = colunas[c];
    const canto = c === 0 ? "border-radius:8px 0 0 0;" : (c === colunas.length - 1 ? "border-radius:0 8px 0 0;" : "");
    h += "<td bgcolor='#F9FAFB' align='" + (col.a || "left") + "'" + (col.w ? " width='" + col.w + "'" : "") + " class='wp-soft wp-m" + (col.oculta ? " wp-hide" : "") + "'" +
      " style='background:#F9FAFB;padding:10px 12px;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;" + canto + "'>" + wpEsc(col.t) + "</td>";
  }
  h += "</tr>";
  if (linhas.length === 0) {
    h += "<tr><td colspan='" + colunas.length + "' class='wp-bd wp-m' style='border-top:1px solid #F3F4F6;padding:14px 12px;" + WP_F + "font-size:13px;color:#6B7280;'>Nada para mostrar.</td></tr>";
  }
  for (let i = 0; i < linhas.length; i++) {
    h += "<tr>";
    for (let c = 0; c < colunas.length; c++) {
      const col = colunas[c];
      h += "<td" + (col.a ? " align='" + col.a + "'" : "") + " valign='middle' class='wp-bd wp-t" + (col.oculta ? " wp-hide" : "") + "'" +
        " style='border-top:1px solid #F3F4F6;padding:10px 12px;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:18px;'>" + (linhas[i][c] === undefined ? "" : linhas[i][c]) + "</td>";
    }
    h += "</tr>";
  }
  h += "</table>" + (nota ? "<p class='wp-m' style='margin:8px 2px 0 2px;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:17px;'>" + nota + "</p>" : "") + "</td></tr>";
  return h;
}

// Pílula de destaque (para dentro de uma célula). a: "left" | "right". Texto curto (até 3 caracteres) vira círculo,
// como a posição do ranking do Guardião.
function wpBadge(texto, estilo, a) {
  const nome = WP_ESTILOS[estilo] ? estilo : "neutro";
  const e = nome === "neutro" ? { bg: "#F3F4F6", cor: "#5B6170" } : WP_ESTILOS[nome];
  const t = String(texto === null || texto === undefined ? "" : texto);
  const alinhar = a === "right" ? " align='right'" : "";
  if (t.length <= 3) {
    return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td width='24' height='24' align='center' valign='middle' bgcolor='" + e.bg + "' style='width:24px;height:24px;background:" + e.bg + ";border-radius:12px;" + WP_F + "font-size:12px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:24px;'>" + wpEsc(t) + "</td></tr></table>";
  }
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:20px;padding:3px 10px;" + WP_F + "font-size:11px;font-weight:bold;color:" + e.cor + ";white-space:nowrap;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(t) + "</td></tr></table>";
}

// Barra proporcional (para dentro de uma célula). pct 0-100; forte = verde-oliva cheio, senão oliva claro
function wpBarra(pct, forte) {
  const w = Math.max(4, Math.min(100, Math.round(pct)));
  const cor = forte ? "#5A6344" : "#BFC4AC";
  return "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:6px;'><tr>" +
    "<td width='" + w + "%' height='6' bgcolor='" + cor + "' style='height:6px;background:" + cor + ";border-radius:3px;font-size:0;line-height:0;'>&nbsp;</td>" +
    (w < 100 ? "<td width='" + (100 - w) + "%' height='6' style='height:6px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table>";
}

// Botão quadrado com seta (para dentro de uma célula): abre a planilha ou lista da linha
function wpSeta(url, titulo) {
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0' align='right'><tr><td width='32' height='32' align='center' valign='middle' bgcolor='#303030' style='width:32px;height:32px;background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' title='" + wpEsc(titulo) + "' aria-label='" + wpEsc(titulo) + "' style='display:block;width:32px;" + WP_F + "font-size:18px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:32px;border-radius:8px;'>&rarr;</a></td></tr></table>";
}

// Botão de chamada (linha própria)
function wpBotao(url, rotulo) {
  return "<tr><td class='wp-pad' align='left' style='padding:16px 32px 8px 32px;'><table role='presentation' cellpadding='0' cellspacing='0' border='0'><tr><td align='center' bgcolor='#303030' style='background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' style='display:block;padding:12px 24px;" + WP_F + "font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:20px;border-radius:8px;'>" + wpEsc(rotulo) + "</a></td></tr></table></td></tr>";
}

// Caixa de aviso (linha própria): titulo + corpo em HTML
function wpAviso(titulo, corpoHtml, estilo) {
  const nome = WP_ESTILOS[estilo] ? estilo : "medio";
  const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
  const cls = nome === "forte" ? "medio" : nome;
  return "<tr><td class='wp-pad' style='padding:16px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border:1px solid " + e.borda + ";border-radius:8px;padding:16px 18px;'>" +
    "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(titulo) + "</p>" +
    "<p class='wp-t' style='margin:8px 0 0 0;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:20px;'>" + corpoHtml + "</p></td></tr></table></td></tr>";
}
// ============================================================
// FIM DO PADRÃO DE E-MAIL WAIPE
// ============================================================

const c = $node["Consolidar Clientes e Calcular Status"].json;
const urlPlanilha = String($node["Criar Planilha do Resultado"].json.spreadsheetUrl || "");
const faixas = Array.isArray(c.faixas) ? c.faixas : [];
const linhas = faixas.map(function (f) {
  return [wpEsc(f.status), '<span style="color:#6B7280;">' + wpEsc(f.texto) + "</span>", "<b>" + wpNum(f.qtd) + "</b>"];
});

const miolo =
  wpKpis([
    { rotulo: "Clientes na planilha", valor: wpNum(c.total_clientes) },
    { rotulo: "Vinculados ao Ploomes", valor: wpNum(c.clientes_vinculados_ploomes) },
    { rotulo: "Sem contato em 18 meses", valor: wpNum(c.sem_contato_registrado), estilo: c.sem_contato_registrado > 0 ? "alerta" : "neutro" }
  ]) +
  wpSecao("Distribuição por status", "Pela data da última compra no Gestor.") +
  wpTabela([{ t: "Status", w: "120" }, { t: "Faixa", oculta: true }, { t: "Clientes", a: "right", w: "80" }], linhas) +
  (urlPlanilha ? wpBotao(urlPlanilha, "Abrir planilha no Google Sheets") : "");

const html = wpPagina({
  titulo: CONFIG.titulo,
